import { Component, computed, input } from '@angular/core';

/** hrm-sparkline — đồ thị đường/vùng mini (không trục, không nhãn) để nhúng vào thẻ chỉ số,
 *  ô bảng: xu hướng headcount 6 tháng, OT theo tuần. SVG tự vẽ, màu token, tự scale min–max. */
@Component({
  selector: 'hrm-sparkline',
  template: `
    <svg [attr.width]="width()" [attr.height]="height()" [attr.viewBox]="'0 0 ' + width() + ' ' + height()">
      @if (variant() === 'area') {
        <polygon [attr.points]="areaPoints()" [attr.fill]="fillColor()" />
      }
      <polyline
        [attr.points]="linePoints()"
        fill="none"
        [attr.stroke]="color()"
        stroke-width="1.5"
        stroke-linecap="round"
        stroke-linejoin="round" />
    </svg>
  `,
  host: { class: 'hrm-sparkline' },
  styles: [`
:host { display: inline-flex; line-height: 0; }
  `],
})
export class HrmSparkline {
  readonly data = input<number[]>([]);
  readonly variant = input<'line' | 'area'>('line');
  readonly width = input(120);
  readonly height = input(36);
  /** Màu đường — token (mặc định màu chính). */
  readonly color = input('var(--primary-base)');

  private readonly pts = computed(() => {
    const d = this.data();
    if (d.length < 2) return [];
    const w = this.width(), h = this.height(), pad = 2;
    const min = Math.min(...d), max = Math.max(...d);
    const span = max - min || 1;
    return d.map((v, i) => {
      const x = pad + (i / (d.length - 1)) * (w - pad * 2);
      const y = pad + (1 - (v - min) / span) * (h - pad * 2);
      return [Math.round(x * 10) / 10, Math.round(y * 10) / 10] as const;
    });
  });

  protected readonly linePoints = computed(() => this.pts().map(([x, y]) => `${x},${y}`).join(' '));

  /** Vùng tô = đường + đóng xuống đáy. */
  protected readonly areaPoints = computed(() => {
    const p = this.pts();
    if (!p.length) return '';
    const h = this.height();
    const first = p[0], last = p[p.length - 1];
    return `${this.linePoints()} ${last[0]},${h} ${first[0]},${h}`;
  });

  /** Màu vùng = màu đường pha loãng 15% trên nền trong suốt. */
  protected readonly fillColor = computed(() => `color-mix(in srgb, ${this.color()} 15%, transparent)`);
}
